import Router from 'next/router';
import { useDispatch, useSelector } from 'react-redux';

import {
  applyUserCustomFilter,
  getFilterPropertyRemoteData,
  addSegmentV2,
  applyAiSessionsPageApi,
} from 'redux/actions/filter';
import {
  mappedPageType,
  mappedSegmentType,
  tableValueMap,
} from 'Utils/helpers/commonUtils';
import {
  callSessionStatisticsAPI,
  callEventsListAndGraphApi,
  applyScreenFlowFilter,
  setActivityFilterSegment,
} from 'redux/actions/megaFilter';
import {
  fetchPlanHatApi,
} from 'redux/actions/common';
import { notInOperators, isOptionsPredefined, singleValueType, screenNameAttributes, GestureViewType } from 'components/shared/GlobalFilter/components/utils'

import { useUpdateScreenFlowImages } from 'components/features/heatmaps/hooks';
import map from 'lodash/map';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import { useMemo } from 'react';

const useAppFilter = () => {
  const dispatch = useDispatch();
  const {
    megaFilterReducer: { selectedAttributeProps },
    urlReducer: { parentType, issueid, issueType, issuepage, appId, starttime, sessionid, issuedetailpage, sessionpage },
    screenRenamedList,
    appFilter,
  } = useSelector((state) => state);

  const { dateSegment, fetchProperty: {
    screen_name: {
      data: screenList
    } = {}
  }} = appFilter;

  const pageType = mappedPageType[parentType];
  const segmentType = mappedSegmentType[parentType];
  const dataTable = tableValueMap[parentType];

  const screenNameArray = useMemo(() => screenList?.map((item) => item) || [], [screenList]);

  const imgReqBody = useMemo(
    () => ({
      appid: appId,
      date_range: dateSegment,
      filters: [],
      screen_names: screenNameArray && screenNameArray.length > 0 && [...screenNameArray, 'Launch', 'Quit', 'Others'],
    }),
    [appId, dateSegment, screenNameArray]
  );
  
  const { data: screenImageData } = useUpdateScreenFlowImages(imgReqBody);

  const updatedScreenFlowImageArray = useMemo(() => map(screenImageData?.data, obj => {
      const updatedScreenName = screenRenamedList[obj.screenName] || obj.screenName;
      return { ...obj, updatedScreenName }
  }, [screenRenamedList]), [screenImageData, screenRenamedList]);

  const fetchPlanHatApiD = (action) =>
    dispatch(
      fetchPlanHatApi({
        action,
        info: {
          page: parentType === 'statistics' ? 'event analytics' : parentType,
        },
      })
    );

  const applyIssuePageApi = async (segmentProps) => {
    let url;
    let query;
    if (issueid) {
      url = `/app/${appId}/issues/${issueType}/${issuepage || 1}/${issueid}?`;
      query = `appId=${appId}&issueType=${issueType}&parentType=issues&issueid=${issueid}&issuepage=${
        issuepage || 1
      }`;
      if (starttime) {
        url = `/app/${appId}/issues/${issueType}/${
          issuepage || 1
        }/${issueid}/${issuedetailpage}/session/${sessionid}/${starttime}?`;
        query = `appId=${appId}&issueType=${issueType}&parentType=issues&issueid=${issueid}&issuepage=${
          issuepage || 1
        }&issuedetailpage=${
          issuedetailpage || 1
        }&sessionid=${sessionid}&starttime=${starttime}`;
      }
    } else {
      url = `/app/${appId}/issues/${issueType}?`;
      query = `appId=${appId}&issueType=${issueType}&parentType=issues`;
    }
  
    url = urlSegmentEncoder(url, segmentProps ? [...segmentProps] : []);
    Router.push(`/integration?${query}`, `${url}`);
  };


  const callListApi = async (segment, action) => {
    if (segment){
      await dispatch(addSegmentV2(segment));
    } 
    switch (pageType) {
      case 'session':
        if (parentType === 'issues') {
          await applyIssuePageApi(segment);
          return;
        }
        // **HOT FIX: due to some reason for aiSessionsList, url route is not getting updated. This following code is a workaround to fix that
        if (parentType === 'aiSessionsList') {
          await applyAiSessionsPageApi({
            appId,
            sessionid,
            sessionpage,
            starttime
          }, segment);
          return;
        }
        if (parentType === 'screenFlow' || parentType === 'screenBurst')
          dispatch(applyScreenFlowFilter(updatedScreenFlowImageArray));
        else dispatch(callSessionStatisticsAPI());
        break;
      case 'user':
        dispatch(applyUserCustomFilter(1, 'user', true));

        dispatch(
          getFilterPropertyRemoteData(
            {
              attribute: 'user_custom_property',
              filter: [],
              search: '',
              dropdownLimit: 501,
              date_range: dateSegment,
            },
            true
          )
        );
        break;
      case 'event':
        dispatch(callEventsListAndGraphApi());
        break;
      default:
        break;
    }
    if (action) fetchPlanHatApiD(action);
  };  

  // * CX-1876 
  const activityCallListApi = async (segments, triggerApi = true) => {
    if (segments){
      await dispatch(setActivityFilterSegment(segments, 'user'));
    }
      await dispatch(applyUserCustomFilter(1, 'user', true, triggerApi));
      dispatch(
          getFilterPropertyRemoteData(
              {
                  attribute: 'user_custom_property',
                  filter: [],
                  search: '',
                  dropdownLimit: 501,
                  date_range: dateSegment,
              },
              true
          )
      );
  };


  const getPayload = (groupingOptions, inputtedValue, selectedOperator) => {
    let value;
    const { attribute: operatorAttribute, isSearchable } = selectedOperator;
    const {
      valueMapping,
      attribute: filterAttribute,
      table,
    } = selectedAttributeProps || {};
    const dbTable = table;
  
    if (
      isSearchable ||
      (notInOperators.includes(operatorAttribute) && valueMapping)
    )
      value = groupingOptions;
    else value = inputtedValue;
    let attributePayload = filterAttribute;
    
    const type = selectedAttributeProps?.type;
    const propertyKey = 'value';
    let propertyName = selectedAttributeProps?.propertyName;
    const isEventScreen = propertyName === 'activity'
    if (
      isOptionsPredefined(attributePayload) &&
      notInOperators.includes(operatorAttribute)
    )
      value = value.map((v) => v.toLowerCase());
    if (attributePayload === 'session_recorded_hour_of_user' && Array.isArray(value))
      value = value.map((v) => v.replace(/(\d+)\s*(am|pm)/i, (_, hour, period) => `${hour}${period.toUpperCase()}`));
    if (['kUXCam_UserIdentity', 'alias'].indexOf(filterAttribute) > -1) {
      propertyName = filterAttribute;
      attributePayload = 'user_custom_property';
    }
    if ( ( screenNameAttributes.includes(attributePayload) || isEventScreen ) && ![ 'contains_any', 'not_contains_any' ].includes( operatorAttribute ) )
      value = Array.isArray(value) ? value.map((v) => v) : value;
    if (attributePayload === 'viewtype') { 
      value = GestureViewType.filter(item => value.includes(item.title.toLowerCase())).map(item => item.value);
    }
    
    const newFilter = [
      {
        attribute: attributePayload,
        operator: singleValueType.includes(type) ? 'equal' : operatorAttribute,
        property_name: propertyName,
        [propertyKey]: value,
        table: dbTable,
      },
    ];
    return newFilter;
  };
  return {
    callListApi,
    pageType,
    segmentType,
    getPayload,
    dataTable,
    activityCallListApi
  };
};
export default useAppFilter;
