const CACHE_DURATION_SLOW = 30 * 60 * 1000; // 30 minutes for slow responses
const CACHE_DURATION_FAST = 2 * 60 * 1000; // 2 minutes for fast responses
const FAST_RESPONSE_THRESHOLD = 2000; // 2 seconds

class ScreenListCache {
  constructor() {
    this.cache = new Map();
    this.pendingRequests = new Map();
  }

  // eslint-disable-next-line class-methods-use-this
  generateKey(reqBody) {
    const normalizeTimestamp = (timestamp) => {
      if (!timestamp) return null;
      const date = new Date(timestamp);
      date.setMinutes(0, 0, 0); // Round down to the hour
      return date.toISOString();
    };

    const normalizedValue = reqBody.date_range?.value ? {
      lower: normalizeTimestamp(reqBody.date_range.value.lower),
      upper: normalizeTimestamp(reqBody.date_range.value.upper),
    } : null;

    const normalizedDateRange = reqBody.date_range ? {
      operator: reqBody.date_range.operator,
      labelId: reqBody.date_range.labelId,
      value: normalizedValue,
    } : null;

    return JSON.stringify({
      appid: reqBody.appid,
      date_range: normalizedDateRange,
      filters: reqBody.filters,
      orderBy: reqBody.orderBy,
    });
  }

  get(reqBody) {
    const key = this.generateKey(reqBody);
    const cached = this.cache.get(key);

    if (!cached) {
      return null;
    }

    const now = Date.now();
    const age = now - cached.timestamp;

    // Use shorter cache duration for fast responses to show new sessions quickly
    const cacheDuration = cached.duration < FAST_RESPONSE_THRESHOLD
      ? CACHE_DURATION_FAST
      : CACHE_DURATION_SLOW;

    const isExpired = age > cacheDuration;

    if (isExpired) {
      this.cache.delete(key);
      return null;
    }

    return {
      data: cached.data,
      timestamp: cached.timestamp,
      age,
    };
  }

  set(reqBody, data, duration) {
    const key = this.generateKey(reqBody);
    this.cache.set(key, {
      data,
      timestamp: Date.now(),
      duration,
    });
    this.pendingRequests.delete(key);
  }

  async getOrFetch(reqBody, fetchFn) {
    const key = this.generateKey(reqBody);

    const cached = this.get(reqBody);
    if (cached) {
      return { data: cached.data, fromCache: true, timestamp: cached.timestamp };
    }

    if (this.pendingRequests.has(key)) {
      const pendingPromise = this.pendingRequests.get(key);
      return pendingPromise;
    }

    const promise = (async () => {
      try {
        const { data, duration } = await fetchFn();
        this.set(reqBody, data, duration);
        return { data, fromCache: false, timestamp: Date.now() };
      } catch (error) {
        this.pendingRequests.delete(key);
        throw error;
      }
    })();

    this.pendingRequests.set(key, promise);
    return promise;
  }

  clear(appid) {
    if (!appid) {
      this.cache.clear();
      return;
    }

    const keysToDelete = [];
    this.cache.forEach((value, key) => {
      try {
        const parsedKey = JSON.parse(key);
        if (parsedKey.appid === appid) {
          keysToDelete.push(key);
        }
      } catch (e) {
        // ignore
      }
    });

    keysToDelete.forEach(key => this.cache.delete(key));
  }

  invalidate(reqBody) {
    const key = this.generateKey(reqBody);
    this.cache.delete(key);
  }

  getAll() {
    return Array.from(this.cache.entries()).map(([key, value]) => ({
      key: JSON.parse(key),
      ...value,
      age: Date.now() - value.timestamp,
    }));
  }
}

export const screenListCache = new ScreenListCache();
