const sortArrayOfObj = (arrayList, key) =>
  arrayList.length &&
  arrayList.sort((a, b) => {
    const c = a[key].toLowerCase();
    const d = b[key].toLowerCase()
    if (c < d) return -1
    if (c > d) return 1
    return 0
  })
const isOptionsPredefined = (attribute) => [ 'session_recorded_weekday','session_recorded_hour_of_user', 'session_network_type', 'viewtype', 'uxcamuserid_cohort', 'session_weekday'].indexOf(attribute) > -1
