const titleWithSeparator = (isTooltip, options) => {
  let commonSeparator = ''
  try {
    return (
      isArray(options) &&
      map(options, (value, key, list) => {
        if (list.length === 5 && key !== list.length - 1)
          commonSeparator = ',  ';
        else if (isTooltip)
          commonSeparator = key < list.length - 1 ? ', \u00A0' : '';
        else if (key < list.length - 1) {
          if (key === 4) commonSeparator = ',\u00A0...';
          else if (key <= 4) commonSeparator = ', \u00A0';
          else commonSeparator = '';
        } else if (key === 'lower') commonSeparator = '\u00A0and\u00A0';
        else commonSeparator = '';

        if (isTooltip || ['lower', 'upper'].includes(key) || key <= 4)
          return (
            <span key={value}>
               {value === '__undefined__' ? <em>{value}</em> : value}
              {commonSeparator}
            </span>
          );
        return <> </>;
      })
    );
  } catch (error) { rollbar.error(error); return <> </> }
}
