const setPlaceholder = (string, title) => {
  let prefix
  if (title) {
    if (['SDK version', 'OS version'].includes(title))
      prefix = title
    else if ([
      'Custom user properties',
      'Custom user properties',
      'Event properties',
    ].includes(title)) {
      if (['Custom user properties', 'Custom user properties'].includes(title))
        prefix = 'custom user property'
      else
        prefix = 'event property'
    } else prefix = title.toLowerCase()
  } else prefix = ''
  return  `${string} ${prefix}`
}
const screenNameAttributes = ['session_screen_list', 'next_screen_name', 'previous_screen_name', 'event_activity_name', 'screen_name']

const dataWithSeparator = (isTooltip, options) => {
  let commonSeparator = ''
  try {
    return (
      isArray(options) &&
      map(options, (value, key, list) => {
        if (list.length === 3 && key !== list.length - 1)
          commonSeparator = ',  ';
        else if (isTooltip)
          commonSeparator = key < list.length - 1 ? ', \u00A0' : '';
        else if (key < list.length - 1) {
          if (key === 3) commonSeparator = `,\u00A0 +${list?.length - 4} others`;
          else if (key <= 3) commonSeparator = ', \u00A0';
          else commonSeparator = '';
        } else if (key === 'lower') commonSeparator = '\u00A0and\u00A0';
        else commonSeparator = '';

        if (isTooltip || ['lower', 'upper'].includes(key) || key <= 3)
          return (
            <span key={value}>
              {value}
              {commonSeparator}
            </span>
          );
        return <> </>;
      })
    );
  } catch (error) { rollbar.error(error); return <> </> }
}

const showOverflowItems = (options) => {
  if (!options?.length) return '';
  const items = options.slice(0, 3);
  const overFlowitems = options.slice(3);
  const newItems = items?.map(item => item?.length > 31 ? `${item.substr(0, 31)}...` : item)
  const title = newItems.join(", ");
  if (options.length > 3) {
    const {length} = overFlowitems;
    const label = `${title}, + ${length} other${length !== 1 ? "s" : ""}`;
    return label
  }
  return title;
}
const hasDisabledSegmentInEvent = (filterSegments, parentType) => {
  let found = false;
    if(parentType === 'eventsList' || parentType === 'statistics' || parentType === 'nocodeEventsList'){
    for(let i = 0; i < filterSegments.length; i += 1 ) {
      if (DisabledFilterSaveSegmentAttributeList.includes(filterSegments[i].attribute)) {
          found = true;
          break;
      }
    }
  }
  return found
}

