const highlightMatchingItems = (segmentText, searchText) => {
  const searchedText = searchText.toLowerCase().replaceAll(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regExp = new RegExp(`(${searchedText.replace(/\s/g, '\\s')})`, 'gi');
  return segmentText
    .split(regExp)
    .map((part, index) => {
      if (part.toLowerCase() === searchedText) {
        return <i key={index + part}>{part}</i>;
      } 
      return part;
      
    });
};

const getEnvTooltip = (env) => {
  switch(env) {
    case '__undefined__':
      return 'Environment is set to undefined when sessions are being captured from older Android SDK version (before 3.6.0) and iOS SDK version (before 3.5.2).'
    case '.alpha':
      return 'Build installed outside of TestFlight or Appstore (iOS) or debug build (Android).'
    case '.beta':
      return 'Build installed from TestFlight (iOS) or release build installed from outside Playstore (Android).'
    case '.release':
      return 'Build installed from Appstore (iOS) or Playstore (Android).'
    default:
      return null;
  }
}

