const viewTypeUtils = {
    getValues: (args) => {
        return args.map(v => GestureViewType.find(i => i.title.toLowerCase().includes(v.toLowerCase()))?.value)
    },

    getTitles: (value) => {
        if(!value){
            return []
        }
        if (!isArray(value)) {
            const item = GestureViewType.find(i => i.value === value);
            return item?.title || GestureViewType[0].title;
        }
        return GestureViewType.filter(i => value.includes(i.value)).map(i => i.title);
    },
};

