/* eslint-disable no-plusplus */
import axios from 'axios';
import { axiosInstance } from 'services/globalInstance'

const { CancelToken } = axios;

class HeatmapApi {

  static async heatmapGestures(data) {
    let heatmapGesturesCancel = null;
    let heatmapGesturesRequest = 0;
    heatmapGesturesRequest++;
    if (heatmapGesturesCancel) {
      await heatmapGesturesCancel(heatmapGesturesRequest);
    }
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/screens/heatmap`,
      data,
      withCredentials: true,
      cancelToken: new CancelToken((c) => {
        heatmapGesturesCancel = c;
        heatmapGesturesRequest = 0;
      }),
    });
    heatmapGesturesCancel = null;
    return response;
  }

  static async heatmapGesturesTrino(data) {
    let heatmapGesturesCancel = null;
    let heatmapGesturesRequest = 0;
    heatmapGesturesRequest++;
    if (heatmapGesturesCancel) {
      await heatmapGesturesCancel(heatmapGesturesRequest);
    }
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/trino/heatmap`,
      data,
      withCredentials: true,
      cancelToken: new CancelToken((c) => {
        heatmapGesturesCancel = c;
        heatmapGesturesRequest = 0;
      }),
    });
    heatmapGesturesCancel = null;
    return response.data;
  }

  static async heatmapScreenshots(data) {
    let cancel = null;
    let request = 0;
    request++;
    if (cancel) {
      await cancel(request);
    }
    const res = await axiosInstance.post(
      `${process.env.PYTHON_API_URL_V2}/screens/heatmap/images`,
      data,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          cancel = c;
          request = 0;
        }),
      }
    );
    cancel = null;
    return res.data;
  }

  static async getScreenStats(data) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/trino/screen_stats`,
      data,
      withCredentials: true,
    });
  }

  static async getHeatmapGesturesTypes(data) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/trino/screen_gesture_types`,
      data,
      withCredentials: true,
    });
  }

  static async getScreenList(data) {
    const result = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/trino/screen_list`,
      data,
      withCredentials: true,
    });
    // Return full response to access pagination info
    return result?.data;
  }

  static async getWebScreenList(data) {
    const result = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/trino/web/screen_list`,
      data,
      withCredentials: true,
    });
    return result?.data;
  }

  static async getScreenDeviceClass (data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/screen_device_class`,
      data,
      withCredentials: true
    })
    return response?.data
  }


  static async getScreenVisitList(data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/screen_visit_list`,
      data,
      withCredentials: true,
    });
    return response?.data?.data
  }

  static async getDeviceClass(data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/top_device_class`,
      data,
      withCredentials: true,
    });
    return response?.data?.data
  }

    static async getScreenImages(data) {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/images`,
      data,
      withCredentials: true,
    });
    return response
  }

  static async areaSpecificHeatmapGestures(data) {
    let heatmapGesturesCancel = null;
    let heatmapGesturesRequest = 0;
    heatmapGesturesRequest++;
    if (heatmapGesturesCancel) {
      await heatmapGesturesCancel(heatmapGesturesRequest);
    }
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/heatmap/area-tooltip`,
      data,
      withCredentials: true,
      cancelToken: new CancelToken((c) => {
        heatmapGesturesCancel = c;
        heatmapGesturesRequest = 0;
      }),
    });
    heatmapGesturesCancel = null;
    return response.data;
  }

  static async fetchHeatmapBox(data){
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/screen_stat_box`,
      data,
      withCredentials: true,
    });
    return response?.data;
  }

  static async fetchHeatmapGraph(data) {
    let cancel = null;
    let request = 0;
    request++;
    if (cancel) {
      await cancel(request);
    }
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL_V2}/screens/screen_stat_graph`,
      data,
      withCredentials: true,
      cancelToken: new CancelToken((c) => {
        cancel = c;
        request = 0;
      }),
    });
    cancel = null;
    return response;
  }
}

export default HeatmapApi;
