import React, { useState, createContext, useContext, useMemo } from 'react';

const ScreensListContext = createContext({
  screensImageLoader: null,
  setScreensImageLoader: () => null
});

const ScreenListContextProvider = ({ children }) => {
  const [screensImageLoader, setScreensImageLoader] = useState(false);
  const value = useMemo(
    () => ({
      screensImageLoader,
      setScreensImageLoader,
    }),
    [
      screensImageLoader,
      setScreensImageLoader,
    ]
  );
  return (
    <ScreensListContext.Provider value={value}>{children}</ScreensListContext.Provider>
  );
};

const useScreenListContext = () => useContext(ScreensListContext);

export {
  ScreenListContextProvider,
  useScreenListContext,
};
