import React, { useState, createContext, useContext, useMemo } from 'react';
import { useSelector } from 'react-redux'
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter'
import { dropdownOptions  as dropdownOptionsProps, dropdownOptionsWithNocode} from 'components/shared/GlobalFilter/components/data-structures-v2'
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext'
import { isEqual } from 'lodash'

const RestrictionContext = createContext(null);
const allowedCategories = [ 'All', 'UX issues' ]

const RestrictionContextProvider = ({ children }) => {
  const [ filtersLockedModal, setFiltersLockedModal ] = useState( false )
  const [ sessionLockedModal, setSessionLockedModal ] = useState( false )
  const [ showPricingModal, setShowPricingModal ] = useState(false)
  const [triggerRequestQuote, setTriggerRequestQuote] = useState(false)

  const { segmentType, pageType } = useAppFilter()
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
  const { urlReducer: { parentType }, appFilter, currentOrgReducer, organizationReducer, currentAppReducer: { isAIEnabled, _id  } } = useSelector( ( state ) => state )

  const advancedFiltersAllowed = useMemo( () => currentOrgReducer?.planFeature?.allowAdvancedFilters === undefined ? true : !!currentOrgReducer?.planFeature?.allowAdvancedFilters , [ currentOrgReducer ] )
  const eventsFeatureAllowed = useMemo( () => currentOrgReducer?.planFeature?.eventAnalysis, [ currentOrgReducer ] )
  const screensFeatureAllowed = useMemo( () => currentOrgReducer?.planFeature?.screenAnalysis, [ currentOrgReducer ] )
  const appFlowsFeatureAllowed = useMemo( () => currentOrgReducer?.planFeature?.screenFlow, [ currentOrgReducer ] )
  const funnelsFeatureAllowed = useMemo( () => currentOrgReducer?.planFeature?.funnelFeature, [ currentOrgReducer ] )
  const issuesFeatureAllowed = useMemo( () => currentOrgReducer?.planFeature?.issueAnalytics, [ currentOrgReducer ] )
  const planFeatureAiSessions = useMemo( () => currentOrgReducer?.planFeature?.tara, [ currentOrgReducer ] )
  const retentionFeatureAllowed = useMemo( () => {
    const featureValue = currentOrgReducer?.planFeature?.retentionAnalytics
    return typeof featureValue === 'undefined' ? false : !!featureValue
  }, [ currentOrgReducer ] )
  const alertsFeatureAllowed = useMemo( () => {
    const featureValue = currentOrgReducer?.planFeature?.alerts
    const allowed = typeof featureValue === 'undefined' ? false : !!featureValue
    return allowed
  }, [ currentOrgReducer ] )
  const aiSessionFeatureAllowed = useMemo( () => {
    return !!(planFeatureAiSessions && isAIEnabled)
  }, [planFeatureAiSessions, isAIEnabled] )

  const trialFlag = useMemo( () => currentOrgReducer?.planType === 'trial', [ currentOrgReducer ] )

  const showEventsPageLockScreen = useMemo( () => !eventsFeatureAllowed && [ 'statistics', 'eventsList' ].includes( parentType ), [ parentType, eventsFeatureAllowed ] )
  const showScreensPageLockScreen = useMemo( () => !screensFeatureAllowed && [ 'heatmapsList' ].includes( parentType ), [ parentType, screensFeatureAllowed ] )
  const showAppFlowsPageLockScreen = useMemo( () => !appFlowsFeatureAllowed && [ 'screenFlow', 'screenBurst' ].includes( parentType ), [ parentType, appFlowsFeatureAllowed ] )
  const showFunnelsPageLockScreen = useMemo( () => !funnelsFeatureAllowed && [ 'funnels' ].includes( parentType ), [ parentType, funnelsFeatureAllowed ] )
  const showIssuesPageLockScreen = useMemo( () => !issuesFeatureAllowed && [ 'issues' ].includes( parentType ), [ parentType, issuesFeatureAllowed ] )

  const pageIsLocked = showEventsPageLockScreen || showScreensPageLockScreen || showAppFlowsPageLockScreen || showFunnelsPageLockScreen || showIssuesPageLockScreen
  const selfServeCheckout = useMemo( () => organizationReducer?.length && organizationReducer.find( ( org ) => org[ '_id' ] === currentOrgReducer.orgId )?.selfServeCheckout, [ currentOrgReducer, organizationReducer ] )
  const freePlanFlag = useMemo( () => currentOrgReducer?.planType === 'free', [ currentOrgReducer ] )
  const videoPlaybackAccessibleTime = useMemo( () => currentOrgReducer?.planLimit?.videoPlaybackAccessibleTime, [ currentOrgReducer ] )

	const currentSegment = appFilter[ segmentType ]
  const dropdownOptions = useMemo( () => noCodeEventsFeatureFlag ? dropdownOptionsWithNocode : dropdownOptionsProps, [ noCodeEventsFeatureFlag ] )
  const filterOptions = useMemo( () => dropdownOptions[ pageType ], [ pageType, dropdownOptions ] )
	const allowedCategoriesInFreePlanWithoutAll = React.useMemo( () => allowedCategories.filter( ( item ) => item !== 'All' ), [] )
	const filterOptionsWithoutNotAllowedCategories = Object.keys( filterOptions || {} ).reduce( ( acc, key ) => {
		if ( allowedCategoriesInFreePlanWithoutAll.includes( key ) ) {
			acc[ key ] = filterOptions[ key ]
		}
		return acc
	}, {} )

  const allowedFilterObjects = React.useMemo( () => Object.values( filterOptionsWithoutNotAllowedCategories ).flatMap( el => el ), [ filterOptionsWithoutNotAllowedCategories ] )
  const allowedFilterAttributes = React.useMemo( () => allowedFilterObjects.map( el => el.attribute ), [ allowedFilterObjects ] )
  const eventBasedAttributes = allowedFilterObjects.flatMap( el => el.default ).filter( el => el  )
  
	const notAllowedFiltersApplied = React.useMemo( () => {
    return currentSegment?.segment.some( segment => {
      const { attribute } = segment
      if ( attribute === "event_name" ) {
        if ( eventBasedAttributes.some( attr => isEqual( attr, segment ) ) ) {
          return false
        }
        return true
      }
      return !allowedFilterAttributes.includes( attribute )
    } )
  }, [ currentSegment, allowedFilterAttributes, eventBasedAttributes ] )

  const value = useMemo( () => ( {
    allowedCategoriesInFreePlan: allowedCategories,
    filterOptionsWithoutNotAllowedCategories,
    notAllowedFiltersApplied,
    filtersLockedModal,
    setFiltersLockedModal,
    sessionLockedModal,
    setSessionLockedModal,
    selfServeFlag: selfServeCheckout,
    freePlanFlag,
    trialFlag,
    monthsOfVideosAccessible: videoPlaybackAccessibleTime,
    showPricingModal,
    setShowPricingModal,
    triggerRequestQuote,
    setTriggerRequestQuote,
    
    pageIsLocked,
    showEventsPageLockScreen,
    showScreensPageLockScreen,
    showAppFlowsPageLockScreen,
    showFunnelsPageLockScreen,
    showIssuesPageLockScreen,
    advancedFiltersAllowed,
    eventsFeatureAllowed,
    screensFeatureAllowed,
    appFlowsFeatureAllowed,
    funnelsFeatureAllowed,
    issuesFeatureAllowed,
    retentionFeatureAllowed,
    alertsFeatureAllowed,
    aiSessionFeatureAllowed,
    planFeatureAiSessions,
  } ), [filterOptionsWithoutNotAllowedCategories, alertsFeatureAllowed, notAllowedFiltersApplied, filtersLockedModal, sessionLockedModal, selfServeCheckout, freePlanFlag, trialFlag, videoPlaybackAccessibleTime, showPricingModal, triggerRequestQuote, pageIsLocked, showEventsPageLockScreen, showScreensPageLockScreen, showAppFlowsPageLockScreen, showFunnelsPageLockScreen, showIssuesPageLockScreen, advancedFiltersAllowed, eventsFeatureAllowed, screensFeatureAllowed, appFlowsFeatureAllowed, funnelsFeatureAllowed, issuesFeatureAllowed, retentionFeatureAllowed, aiSessionFeatureAllowed, planFeatureAiSessions] )

  return (
    <RestrictionContext.Provider value={ value }>
      { children }
    </RestrictionContext.Provider>
  );
};

const useRestrictionContext = () => useContext( RestrictionContext )

export { RestrictionContextProvider, useRestrictionContext }