// const PAGINATION_LIMIT = 25
const screenImageApiSupportedFilter = [
  'device_class',
  'app_version',
  'device_platform',
  'device_os_version',
];

const getScreenList = async ({ postBody }) => {
  const startTime = Date.now();
  const response = await HeatmapApi.getScreenList(postBody);
  const duration = Date.now() - startTime;
  // Return data, pagination, and orderBy from API response
  return {
    data: response?.data,
    pagination: response?.pagination,
    orderBy: response?.orderBy,
    duration
  };
};

const getWebScreenList = async({ postBody }) => HeatmapApi.getWebScreenList(postBody);

export const useWebScreenListQuery = (postBody, queryKy = 'web-screen-table-list', isWebApp = false) => {
  const queryDep = useMemo(() => [queryKy, postBody], [queryKy, postBody]);
  return useQuery(queryDep, () => getWebScreenList({ postBody }), {
    refetchInterval: defaultRefetchInterval,
    retry: false,
    refetchOnWindowFocus: false,
    refetchOnmount: false,
    refetchOnReconnect: false,
    enabled: isWebApp && Boolean(postBody.appid),
    keepPreviousData: true,
  })
};

export const useScreenListQuery = (postBody, queryKy = 'screen-table-list', isWebApp = false) => {
  const queryDep = useMemo(() => [queryKy, postBody], [queryKy, postBody]);
  const [lastUpdate, setLastUpdate] = useState(null);

  // Check if this is a paginated request (page > 50)
  const isPaginatedRequest = postBody?.page && postBody.page > 50;

  const queryResult = useQuery(queryDep, async () => {
    // For paginated requests (page 51+), skip cache and fetch directly
    if (isPaginatedRequest) {
      return getScreenList({ postBody });
    }
    // For initial requests (pages 1-50), use cache
    const result = await screenListCache.getOrFetch(
      postBody,
      () => getScreenList({ postBody })
    );
    setLastUpdate(result.timestamp);
    return result.data;
  }, {
    staleTime: isPaginatedRequest ? 0 : Infinity,
    cacheTime: isPaginatedRequest ? 5 * 60 * 1000 : Infinity, // 5 min cache for paginated requests
    refetchInterval: false,
    retry: false,
    refetchOnWindowFocus: false,
    refetchOnmount: false,
    refetchOnReconnect: false,
    enabled: !isWebApp && Boolean(postBody.appid),
  });

  useEffect(() => {
    if (queryResult.data && !lastUpdate && !isPaginatedRequest) {
      const cached = screenListCache.get(postBody);
      if (cached) {
        setLastUpdate(cached.timestamp);
      }
    }
  }, [queryResult.data, lastUpdate, postBody, isPaginatedRequest]);

  const refresh = useCallback(async () => {
    screenListCache.invalidate(postBody);
    return queryResult.refetch();
  }, [postBody, queryResult]);

  // Handle both cached (old format: array) and new format (object with data/pagination)
  const responseData = queryResult.data;
  // Check if response is an array (old cache format) or object (new format)
  const isOldFormat = Array.isArray(responseData);
  const screenData = isOldFormat ? responseData : responseData?.data;
  const paginationInfo = isOldFormat ? null : responseData?.pagination;

  return {
    ...queryResult,
    data: screenData,
    pagination: paginationInfo,
    lastUpdate,
    refresh,
  };
};
