export const useUpdateScreenFlowImages = (data) => {
  const { appid, screen_names } = data;
  const screenFlowImageQueryKey = ['screen-flow-images', appid];
  const queryClient = useQueryClient();
  const screenFlowImages = useMemo(() => queryClient.getQueryData(screenFlowImageQueryKey), [screenFlowImageQueryKey]);
  const existingScreenNames = screenFlowImages?.data?.map((item) => item.screenName);
  const newScreenNames = difference(screen_names, existingScreenNames);
  useScreenFlowImages(data, 0, '', screen_names && screen_names.length > 0 && !screenFlowImages);
  const screensToFetchData = {
    ...data,
    screen_names: newScreenNames
  }
  const { data: newImagesData } = useScreenImages(screensToFetchData, 0, '', null, existingScreenNames && existingScreenNames.length > 0 && newScreenNames.length > 0)
  
  if(existingScreenNames && existingScreenNames.length > 0 && newScreenNames.length > 0 && newImagesData) {
    // eslint-disable-next-line no-unsafe-optional-chaining
    const updatedScreenFlowImages = [...screenFlowImages?.data, ...newImagesData?.data];
    queryClient.setQueryData(screenFlowImageQueryKey, {
      data: updatedScreenFlowImages
    });

    return {
      data: updatedScreenFlowImages
    }
  }
  return {
    data: screenFlowImages || []
  };
}

export const useScreensImageList = ({
  screenNames = [],
  paginationLimit,
  screensListReqBody,
  screenSearchText
}) => {
  const { setScreensImageLoader } = useScreenListContext()
  const queryClient = useQueryClient();
  const screensListQueryKy = ['screen-table-list', screensListReqBody];

  const { appid, date_range: dateSegment, filters } = screensListReqBody;

  const filtersCopy = useMemo(
    () => filters?.length > 0 && filters?.filter((v) => screenImageApiSupportedFilter.includes(v.attribute)),
    [filters]
  );

  const screensImageReqBody = useMemo(
    () => ({
      appid,
      screen_names: screenNames,
      date_range: dateSegment,
      filters: filtersCopy || [],
    }),
    [appid, screenNames, dateSegment, filtersCopy]
  );

  const onSuccessCallback = (data) => {
    queryClient.setQueryData(screensListQueryKy, (OldData) => {
      const isArray = Array.isArray(OldData);
      const currentData = isArray ? OldData : OldData?.data;

      if (!currentData) return OldData;

      const newData = currentData.map((v) => {
        const screenIndex = data.data.findIndex(
          ({ screenName }) => screenName === v.screenname
        );
        if (screenIndex > -1) {
          const { screenShotImageUrl } = data.data[screenIndex];
          return {
            ...v,
            screenShotImageUrl,
          };
        }
        return v;
      });

      if (isArray) {
        return newData;
      }

      return {
        ...OldData,
        data: newData,
      };
    });
  };
  
  const { isLoading } = useScreenImages(
    screensImageReqBody,
    paginationLimit + 1,
    screenSearchText,
    onSuccessCallback,
  );
  setScreensImageLoader(isLoading)
};
